// Entity Sparse Vector Protocol (ESVP)
class EntityProtocol {
  static encode(value) {
    return [0, 0, 0, value];
  }

  static decode(vector) {
    if (this.validate(vector)) {
      return vector[3];
    }
    return null;
  }

  static validate(vector) {
    return Array.isArray(vector) &&
           vector.length === 4 &&
           vector.slice(0, 3).every(v => v === 0);
  }
}

